code.python:
def reverseBits(n):
    result = 0
    for _ in range(32):
        result = (result << 1) | (n & 1)
        n >>= 1
    return result

code.cpp:
class Solution {
public:
    uint32_t reverseBits(uint32_t n) {
        uint32_t result = 0;
        for (int i = 0; i < 32; i++) { result = (result << 1) | (n & 1); n >>= 1; }
        return result;
    }
};

code.java:
class Solution {
    public int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) { result = (result << 1) | (n & 1); n >>>= 1; }
        return result;
    }
}

code.js:
var reverseBits = function(n) {
    let result = 0;
    for (let i = 0; i < 32; i++) { result = (result << 1) | (n & 1); n >>>= 1; }
    return result >>> 0;
};

code.python:
def missingNumber(nums):
    return len(nums) * (len(nums)+1) // 2 - sum(nums)
# Or XOR: xor 0..n with all nums, result is missing

code.cpp:
class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size(), result = n;
        for (int i = 0; i < n; i++) result ^= i ^ nums[i];
        return result;
    }
};

code.java:
class Solution {
    public int missingNumber(int[] nums) {
        int n = nums.length, result = n;
        for (int i = 0; i < n; i++) result ^= i ^ nums[i];
        return result;
    }
}

